import itertools

def solve_pairing(n):
    numbers = list(range(1, 2 * n + 1))
    differences = list(range(1, n + 1))

    # We need to find a perfect matching in a graph where the edges correspond 
    # to differences 1..n, such that every difference is used exactly once.

    # Backtracking approach

    def find_pairing(available_numbers, remaining_diffs):
        if not remaining_diffs:
            return True, [] # Success

        if not available_numbers:
            return False, [] # Failure

        # Pick the smallest available number
        u = min(available_numbers)

        for d in list(remaining_diffs):
            v = u + d

            if v <= 2 * n and v in available_numbers:
                # Try pairing (u, v)
                new_available = available_numbers - {u, v}
                new_remaining_diffs = remaining_diffs - {d}

                success, pairing = find_pairing(new_available, new_remaining_diffs)

                if success:
                    return True, [(u, v)] + pairing

        return False, []

    # Convert to sets for efficient lookups during recursion
    initial_available = set(numbers)
    initial_diffs = set(differences)

    success, pairing = find_pairing(initial_available, initial_diffs)

    return success, pairing

